text:
.message-header-view-button {
  flex-direction: row;
  min-inline-size: 24px;
  margin: 0;
  padding-inline: 3px;
  fill: color-mix(in srgb, currentColor 20%, transparent);
  stroke: currentColor;

  &[is="toolbarbutton-menu-button"] {
    padding: 0;

    & > .toolbarbutton-menubutton-button {
      flex-direction: row;
      padding-inline: 3px;
    }
  }

  & .toolbarbutton-text {
    padding-inline-start: 2px;
  }
}
